for _ in range(int(input())):
	n = int(input())
	a = input()
	b = input()
	m = 0
	for i in range(n):
		if a[i] == b[i]:
			m += 1
	if n - m & 1:
		print(0)
		continue
	mod = 10 ** 9 + 7
	ans = pow(2, m, mod)
	nr = 1
	dr = 1
	for i in range(1, n - m + 1):
		nr = nr * i % mod
	for i in range(1, (n - m) // 2 + 1):
		dr = dr * i % mod
	for i in range(1, (n - m) // 2 + 1):
		dr = dr * i % mod
	dr = pow(dr, -1, mod)
	print(ans * nr * dr % mod)
